  expect(world.currentWrapper).toBe(outgoing);
  stage.advance();
  finish(world);
  world.jump({ x: -1, y: 0 });
  expect(world.transit!.next).toBe(home);
  expect(home.tutorial).toBe(2);
  expect(world.stats.visited).toBe(1);
  finish(world);
  world.jump({ x: 1, y: 0 });
  expect(world.transit!.next.tutorial).toBe(2);
  expect(world.stats.visited).toBe(1);
});
